  "source": "\"\"\"Read-only AP-side forensic snapshots for original frozen P3B.5 episodes.\"\"\"\nimport hashlib, json, time, os, sys\nfrom datetime import datetime, timezone\nfrom pathlib import Path\nsys.path.insert(0, \"scripts\")\nfrom observer_lifetime import bind_to_owner\nbind_to_owner()\nimport rclpy\nfrom rclpy.utilities import get_rmw_implementation_identifier\nfrom rclpy.node import Node\nfrom rclpy.parameter import Parameter\nfrom rclpy.qos import QoSProfile, ReliabilityPolicy, DurabilityPolicy\nfrom nav_msgs.msg import OccupancyGrid, Odometry\nfrom rcl_interfaces.srv import GetParameters\nfrom tf2_msgs.msg import TFMessage\nfrom std_msgs.msg import String\nfrom rosidl_runtime_py.convert import message_to_ordereddict\n\nepisode = sys.argv[1]\nroot = Path(\"log/p3b5/p3b5_v103_task_ap\") / (episode + \"_ap\")\nresult_path = Path(sys.argv[2])\nroot.mkdir(parents=True, exist_ok=False)\nsource = Path(__file__)\nmetadata = {\"predeclared_at_utc\": datetime.now(timezone.utc).isoformat(),\n            \"commit\": \"dbed34c0ed708803e131ef00ecff7791e6b3cde3\",\n            \"source\": source.read_text(),\n            \"source_sha256\": hashlib.sha256(source.read_bytes()).hexdigest(),\n            \"ros_domain_id\": os.environ[\"ROS_DOMAIN_ID\"],\n            \"started_after_task_runner_run_line\": True,\n            \"prospectively_declared_before_cohort\": True,\n            \"episode\": episode,\n            \"scope\": \"Reactive read-only delivered AP map/odom/TF/battery and task metadata. No publishers/actions or native truth. Post-run forensic use only; no additional episode or control input.\"}\nmetadata['middleware_environment']={key:os.environ.get(key) for key in ('RMW_IMPLEMENTATION','FASTDDS_BUILTIN_TRANSPORTS','FASTRTPS_DEFAULT_PROFILES_FILE')}\n(root / \"metadata.json\").write_text(json.dumps(metadata, indent=2)+\"\\n\")\nrclpy.init()\nmetadata[\"actual_rmw_identifier\"]=get_rmw_implementation_identifier()\nnode = Node(\"p3b5_forensic_ap_snapshot_qos_fixed\", parameter_overrides=[Parameter(\"use_sim_time\", value=True)])\nqos = QoSProfile(depth=1, reliability=ReliabilityPolicy.RELIABLE,\n                 durability=DurabilityPolicy.TRANSIENT_LOCAL)\ngateway_qos = QoSProfile(depth=1, reliability=ReliabilityPolicy.RELIABLE)\nlatest = {}\nsubscriptions = []\ndef receive(key, message):\n    latest[key] = message\nsubscriptions.append(node.create_subscription(OccupancyGrid, \"/merge_map\", lambda m: receive(\"map\", m), 10))\nfor name in (\"tb1\", \"tb2\", \"tb3\"):\n    for topic, kind in ((\"odom\", Odometry), (\"tf\", TFMessage), (\"battery_state\", String)):\n        key = f\"{name}/{topic}\"\n        subscriptions.append(node.create_subscription(kind, f\"/gateway/received/{key}\", lambda m, k=key: receive(k, m), gateway_qos))\nfor topic in (\"task_state\", \"rally_assignments\"):\n    subscriptions.append(node.create_subscription(String, \"/\"+topic, lambda m, k=topic: receive(k, m), qos))\nsubscriptions.append(node.create_subscription(String, \"/gateway/received/target_detection\", lambda m: receive(\"target_detection\", m), gateway_qos))\nparameter_robots = (\"tb1\", \"tb2\", \"tb3\")\nparameter_spec = {}\nfor robot in parameter_robots:\n    for component in (\"controller_server\", \"velocity_smoother\", \"slam_toolbox\"):\n        key = f\"/{robot}/{component}\"\n        parameter_spec[key] = [\"use_sim_time\"] + ([\"map_update_interval\"] if component == \"slam_toolbox\" else [])\nparameter_clients = {key: node.create_client(GetParameters, key + \"/get_parameters\") for key in parameter_spec}\nparameter_pending, parameter_values, parameter_next, parameter_attempts = {}, {}, {}, []\nclock_values, slam_values, map_deliveries = {}, {}, {robot: [] for robot in parameter_robots}\ndef receive_parameters(key, future, attempt):\n    try:\n        response = future.result()\n        if response is None or len(response.values) != len(parameter_spec[key]):\n            attempt[\"response\"] = \"missing or incomplete\"\n            return\n        values = {}\n        for name, value in zip(parameter_spec[key], response.values):\n            values[name] = value.bool_value if value.type == 1 else value.double_value if value.type == 3 else None\n        attempt[\"response\"] = values\n        if all(value is not None for value in values.values()):\n            parameter_values[key] = values\n            if key.endswith(\"/slam_toolbox\"):\n                slam_values[key] = values\n            else:\n                clock_values[key] = values[\"use_sim_time\"]\n    except Exception as error:\n        attempt[\"error\"] = repr(error)\ndef query_parameters():\n    wall = time.monotonic()\n    for key, client in parameter_clients.items():\n        if key in parameter_values:\n            continue\n        pending = parameter_pending.get(key)\n        if pending and not pending[0].done():\n            if wall - pending[1] < 2.:\n                continue\n            client.remove_pending_request(pending[0])\n            pending[0].cancel()\n        if wall < parameter_next.get(key, 0.) or not client.service_is_ready():\n            continue\n        request = GetParameters.Request(); request.names = parameter_spec[key]\n        attempt = dict(node=key, names=list(request.names), observer_time=node.get_clock().now().nanoseconds / 1e9, requested_at_utc=datetime.now(timezone.utc).isoformat())\n        parameter_attempts.append(attempt)\n        future = client.call_async(request)\n        parameter_pending[key] = (future, wall)\n        parameter_next[key] = wall + 2.\n        future.add_done_callback(lambda value, k=key, a=attempt: receive_parameters(k, value, a))\ndef receive_map_delivery(robot, message):\n    source_time = message.header.stamp.sec + message.header.stamp.nanosec / 1e9\n    observer_time = node.get_clock().now().nanoseconds / 1e9\n    map_deliveries[robot].append(dict(source_time=source_time, observer_time=observer_time, source_age_sec=observer_time-source_time))\nfor robot in parameter_robots:\n    subscriptions.append(node.create_subscription(OccupancyGrid, f\"/gateway/received/{robot}/map\", lambda m, r=robot: receive_map_delivery(r, m), gateway_qos))\n\nnext_snapshot = 0.\ndeadline = time.monotonic() + 900.\ncount = 0\noutput = root / \"snapshots.jsonl\"\ntry:\n    with output.open(\"w\") as stream:\n        while time.monotonic() < deadline and not result_path.exists():\n            rclpy.spin_once(node, timeout_sec=.5)\n            query_parameters()\n            now = node.get_clock().now().nanoseconds / 1e9\n            if now > 0 and latest.get(\"map\") and latest.get(\"task_state\") and latest[\"task_state\"].data in (\"EXPLORE\", \"FOUND_UNCONFIRMED\", \"FOUND\", \"RALLY\") and now >= next_snapshot:\n                stream.write(json.dumps({\"observer_time\": now, \"messages\": {k: message_to_ordereddict(v) for k, v in latest.items()}})+\"\\n\")\n                stream.flush()\n                next_snapshot = now + 10.\n                count += 1\nexcept KeyboardInterrupt:\n    pass\nfinally:\n    node.destroy_node()\n    rclpy.try_shutdown()\n    metadata.update(nav2_clock_values=clock_values, slam_map_parameters=slam_values, parameter_values=parameter_values, parameter_query_attempts=parameter_attempts, map_delivery_observations=map_deliveries)\n    metadata.update(finished_at_utc=datetime.now(timezone.utc).isoformat(), snapshots=count,\n                    output_sha256=hashlib.sha256(output.read_bytes()).hexdigest())\n    (root / \"metadata.json\").write_text(json.dumps(metadata, indent=2)+\"\\n\")\n",
