ixed\", parameter_overrides=[Parameter(\"use_sim_time\", value=True)])\nqos = QoSProfile(depth=1, reliability=ReliabilityPolicy.RELIABLE,\n                 durability=DurabilityPolicy.TRANSIENT_LOCAL)\ngateway_qos = QoSProfile(depth=1, reliability=ReliabilityPolicy.RELIABLE)\nlatest = {}\nsubscriptions = []\ndef receive(key, message):\n    latest[key] = message\nsubscriptions.append(node.create_subscription(OccupancyGrid, \"/merge_map\", lambda m: receive(\"map\", m), 10))\nfor name in (\"tb1\", \"tb2\", \"tb3\"):\n    for topic, kind in ((\"odom\", Odometry), (\"tf\", TFMessage), (\"battery_state\", String)):\n        key = f\"{name}/{topic}\"\n        subscriptions.append(node.create_subscription(kind, f\"/gateway/received/{key}\", lambda m, k=key: receive(k, m), gateway_qos))\nfor topic in (\"task_state\", \"rally_assignments\"):\n    subscriptions.append(node.create_subscription(String, \"/\"+topic, lambda m, k=topic: receive(k, m), qos))\nsubscriptions.append(node.create_subscription(String, \"/gateway/received/target_detection\", lambda m: receive(\"target_detection\", m), gateway_qos))\nparameter_robots = (\"tb1\", \"tb2\", \"tb3\")\nparameter_spec = {}\nfor robot in parameter_robots:\n    for component in (\"controller_server\", \"velocity_smoother\", \"slam_toolbox\"):\n        key = f\"/{robot}/{component}\"\n        parameter_spec[key] = [\"use_sim_time\"] + ([\"map_update_interval\"] if component == \"slam_toolbox\" else [])\nparameter_clients = {key: node.create_client(GetParameters, key + \"/get_parameters\") for key in parameter_spec}\nparameter_pending, parameter_values, parameter_next, parameter_attempts = {}, {}, {}, []\nclock_values, slam_values, map_deliveries = {}, {}, {robot: [] for robot in parameter_robots}\ndef receive_parameters(key, future, attempt):\n    try:\n        response = future.result()\n        if response is None or len(response.values) != len(parameter_spec[key]):\n            attempt[\"response\"] = \"missing or incomplete\"\n